#if USE_TINT
#endif
#if CC_USE_MODEL
#endif
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec2 v_uv0;
uniform sampler2D texture;
uniform ARGS {
  float u_dH;
  float u_dS;
  float u_dL;
};
void main () {
  vec4 texColor=texture2D(texture, v_uv0);
  float r=texColor.r;
  float g=texColor.g;
  float b=texColor.b;
  float a=texColor.a;
  float h;
  float s;
  float l;
  {
      float max=max(max(r,g),b);
      float min=min(min(r,g),b);
      if(max==min){
          h=0.0;
      }else if(max==r&&g>=b){
          h=60.0*(g-b)/(max-min)+0.0;
      }else if(max==r&&g<b){
          h=60.0*(g-b)/(max-min)+360.0;
      }else if(max==g){
          h=60.0*(b-r)/(max-min)+120.0;
      }else if(max==b){
          h=60.0*(r-g)/(max-min)+240.0;
      }
      l=0.5*(max+min);
      if(l==0.0||max==min){
          s=0.0;
      }else if(0.0<=l&&l<=0.5){
          s=(max-min)/(2.0*l);
      }else if(l>0.5){
          s=(max-min)/(2.0-2.0*l);
      }
