  h=h+u_dH;
  s=min(1.0,max(0.0,s+u_dS));
  l=l;
  vec4 finalColor;
  {
      float q;
      if(l<0.5){
          q=l*(1.0+s);
      }else if(l>=0.5){
          q=l+s-l*s;
      }
      float p=2.0*l-q;
      float hk=h/360.0;
      float t[3];
      t[0]=hk+1.0/3.0;t[1]=hk;t[2]=hk-1.0/3.0;
      for(int i=0;i<3;i++){
          if(t[i]<0.0)t[i]+=1.0;
          if(t[i]>1.0)t[i]-=1.0;
      }
      float c[3];
      for(int i=0;i<3;i++){
          if(t[i]<1.0/6.0){
              c[i]=p+((q-p)*6.0*t[i]);
          }else if(1.0/6.0<=t[i] && t[i]<0.5){
              c[i]=q;
          }else if(0.5<=t[i] && t[i]<2.0/3.0){
              c[i]=p+((q-p)*6.0*(2.0/3.0-t[i]));
          }else{
              c[i]=p;
          }
      }
      finalColor=vec4(c[0],c[1],c[2],a);
  }
  finalColor+=vec4(u_dL,u_dL,u_dL,0.0);
  gl_FragColor=finalColor;
}

